"""Cohesive decision brief, accessible stage navigation and separate research views."""
import html,re
from compute_report_overview import render as report_overview
E=html.escape

def actions(rows):
 return '<div class="pg-actions">'+''.join('<a class="pg-link" href="'+E(url,quote=True)+'">'+E(label)+' ↗</a>' for label,url in rows)+'</div>'

def overview_view(p,visual,tabs,panels):
 stages=p['site_flow']['stages']
 preview='<ol class="roadmap-preview">'+''.join('<li><a href="timeline.html#stage-'+s['id']+'"><span>'+str(i+1).zfill(2)+'</span>'+E(s['label'])+'</a></li>' for i,s in enumerate(stages))+'</ol>'
 return '''<div class="pg-hero"><div><p class="pg-kicker">UArizona Information Science · proposed teaching program</p><h1>Make teaching<br>less fragile.</h1><p class="pg-lead">A course needs computing that lasts through teaching, assessment and export. Our proposed route is a large ACCESS allocation for both CPU and GPU.</p>'''+actions([('Explore the staged plan','timeline.html'),('Open the five-slide talk','index.html')])+'''<p class="pg-small">Component code is prepared. Provider measurements, an allocation and classroom approval are still pending.</p></div>'''+visual+'''</div>
<section id="problem" class="overview-problem"><p class="pg-kicker">The core problem</p><h2>'''+E(p['core_statement'])+'''.</h2><p>Course plans can outlast the free accounts, classroom tools and hosting they were built on.</p><div class="pg-grid three"><article class="pg-card"><p class="pg-kicker">Classroom coordination</p><h3>GitHub Classroom ended.</h3><p>The August 28, 2026 shutdown ended that tool. Classroom 50 is a workable successor, externally maintained; it adds no Codespaces compute. GitHub repositories remain.</p><a href="classroom50.html">Classroom 50: successor and limits ↗</a></article><article class="pg-card"><p class="pg-kicker">Education benefits</p><h3>The Colab offer closed.</h3><p>New Pro for Education sign-ups were closed when checked October 8. Base free Colab remains; the effective closure date is unknown.</p><a href="evidence.html#colab">Offer and limits ↗</a></article><article class="pg-card"><p class="pg-kicker">Access duration</p><h3>Cloud access can expire.</h3><p>AWS’s new general Free Tier free plan lasts at most six months. This is distinct from campus UITS/AWS testing access.</p><a href="evidence.html#aws">Free Tier boundary ↗</a></article></div><p class="pg-small">Repositories, free hosting, databases and preservation have continuity risks too. <a href="report.html">Review the full report and evidence ↗</a>.</p></section>
<section id="solution"><p class="pg-kicker">The key solution</p><h2>Move required teaching onto an approved service.</h2><p class="pg-lead">Use ACCESS for the classroom CPU and GPU allocation. First test components, measure demand, then prove the teaching and recovery paths.</p><div class="pg-grid three"><article class="pg-card"><span class="route-number">01</span><h3>Test on campus AWS</h3><p>CPU component testing only, using already-authorized UITS access.</p></article><article class="pg-card"><span class="route-number">02</span><h3>Benchmark on free GPUs</h3><p>Kaggle or free Colab measurements before piloting. Their quotas do not reserve a class.</p></article><article class="pg-card"><span class="route-number">03</span><h3>Teach on ACCESS</h3><p>A measured CPU + GPU request, target-system replay and readiness checks. CloudBank is a conditional managed option.</p></article></div><p class="pg-small">NAIRR Classroom remains an additional route for eligible instructor-led AI pilots; it is not an assumed award. Durable support, repositories, recovery and exports are part of the service.</p></section>
<section id="plan"><div class="section-heading"><div><p class="pg-kicker">A staged plan</p><h2>Earn the next step.</h2></div><a href="timeline.html">Timeline, events and gates ↗</a></div>'''+preview+'''<div class="pg-note">Current focus: run the provider benchmarks. Preparation uses six active work weeks; provider review can add waiting time. Course dates are not yet confirmed.</div></section>
<section><p class="pg-kicker">The operating boundary</p><div class="pg-metrics"><div><strong>10 hours/week</strong><span>Greg’s total time, shared with EduCloud</span></div><div><strong>Zero cash</strong><span>Paid needs depend on confirmed eligible grants</span></div><div><strong>Two course concepts</strong><span>Data science + MLIS; actual term and enrollment pending</span></div></div><p class="pg-small">TA and course-lead hours are separate; course leads need no salary. <a href="budget.html">See the hours plan and grant dependencies ↗</a>.</p></section>
<section><p class="pg-kicker">For the people moving this forward</p><h2>Find the decision you own.</h2>'''+tabs+panels+'''</section>'''

def timeline_view(p):
 flow=p['site_flow'];stages=flow['stages'];phases=p['phases']
 nav='<div class="stage-tabs" role="tablist" aria-label="Proposed program stages">'+''.join('<a role="tab" id="stage-tab-'+s['id']+'" href="#stage-'+s['id']+'" data-stage="'+s['id']+'" aria-controls="stage-'+s['id']+'" aria-selected="'+str(i==0).lower()+'"><span class="stage-number">'+str(i+1).zfill(2)+'</span><span>'+E(s['label'])+'</span><small>'+E('Current focus' if i==0 else 'Later stage')+'</small></a>' for i,s in enumerate(stages))+'</div>'
 panels=''
 for i,(s,ph) in enumerate(zip(stages,phases)):
  panels+='<section class="stage-panel" role="tabpanel" id="stage-'+s['id']+'" aria-labelledby="stage-tab-'+s['id']+'" tabindex="0"><div class="stage-panel-heading"><p class="pg-kicker">Stage '+str(i+1)+' / '+str(len(stages))+' · '+E(s['status'])+'</p><p class="stage-time">'+E(ph['when'])+'</p></div><h2>'+E(ph['title'])+'</h2><p class="pg-lead">'+E(s['summary'])+'</p><div class="stage-columns"><div><h3>Key events</h3><ol class="stage-events">'+''.join('<li>'+E(event)+'</li>' for event in s['events'])+'</ol></div><aside class="stage-gate"><p class="pg-kicker">Evidence to advance</p><p>'+E(s['gate'])+'</p></aside></div>'+actions(s['links'])+'<details><summary>Detailed work and exit evidence</summary><p>'+E(ph['body'])+'</p><p><strong>Exit evidence:</strong> '+E(ph['exit'])+'</p></details></section>'
 return '<p class="pg-kicker">Proposed sequence · dates relative to an approved future term</p><h1>Build the evidence.<br>Then teach.</h1><p class="pg-lead">Each stage has a concrete event and a gate. Select a stage to see what happens next; selecting it does not mark work complete.</p><p class="pg-note">Today: runnable component tests and request drafts exist. Campus AWS and actual GPU measurements, the ACCESS award and classroom admission remain pending.</p><div id="stageTimeline">'+nav+'<p id="stageSelection" class="pg-small" aria-live="polite">Stage 1 of 6 selected · current focus: benchmarking.</p>'+panels+'</div><noscript><p>All stages are shown below; stage links jump to their details.</p></noscript><section><h2>Timing follows evidence.</h2><p>Plan six active preparation weeks, fifteen teaching weeks and two closeout weeks. Allocation review or missing approvals can extend the calendar. No term, award date or resource reservation is promised. Required spending must have confirmed eligible grant support; all work assigned to Greg stays inside ten hours/week.</p></section>'

