 rows=[('Credits and billing','serverless-compute.html','Compare Modal and similar platforms','Nine serverless, notebook and model-API options with free-credit, trial, payment and workload boundaries.'),('Assignment workflow','classroom50.html','Consider Classroom 50','Workable GitHub Classroom successor; external stewardship and unchanged Codespaces compute limits.'),('First step','gpu-benchmark.html','Run the benchmarks','CPU DS/MLIS runner, Kaggle/Colab GPU notebooks, exports and the ACCESS sizing helper.'),('After measurements','access-request.html','Prepare the ACCESS request','Review the CPU + GPU draft, required attachments and conditional CloudBank branch.'),('Teaching design','pilot-plan.html','Choose the course components','Proposed INFO 521 and LIS 671 activities, inputs, learner outputs and support responsibilities.'),('Before required use','readiness.html','Check classroom readiness','Thirteen gates for access, assignments, concurrency, submissions, accessibility, recovery and exit.'),('Across the college','degree-options.html','Explore degree-specific work','Assignment-level fits for nine non-cyber information-science degrees.'),('Bounded alternatives','classroom-resources.html','Compare free resources','Codespaces, Kaggle, Codabench and other development, evaluation and demonstration routes.')]
