def report_hub(data):
 source_count=len(data['evidence'])
 rows=[('Commercial compute','serverless-compute.html','Modal and similar platforms','Current free credits, paid usage, notebook limits and DS/MLIS work boundaries.'),('Successor assessment','classroom50.html','Classroom 50, ownership and compute','A workable workflow alternative; source-backed boundaries and checks before adoption.'),('Research map','federal-compute.html','Federal computing and service map','32 platform, product and funding families, including ACCESS, OSG, NRP and IDSS/MESA.'),('Capacity comparison','classroom-assessment.html','Classroom route assessment','Jetstream2 CPU/GPU scenarios and provider questions. Illustrative models, not awarded capacity.'),('Continuity','repository-plan.html','Repositories, hosting and preservation','Ownership, independent backups, restore, portable work and long-term destinations.'),('Structured material','evidence.json','Download the source ledger','Machine-readable claims, scopes, dates and references.')]
 return '<p class="pg-kicker">Research library · separate from the working plan</p><h1>Report & evidence.</h1><p class="pg-lead">An overview of the resources that remain, the limits that matter, and the documented losses behind the proposed teaching service.</p>'+report_overview(data)+'<section id="research-library"><p class="pg-kicker">Read the underlying research</p><h2>Full report and evidence.</h2><div class="research-entry-grid"><article class="pg-card research-entry"><p class="pg-kicker">The complete narrative</p><h2>Full report</h2><p>Compute access losses, repository changes, hosting/database withdrawals, federal resources and the proposed teaching program.</p>'+actions([('Read the full report','research-report.html'),('Download original text','research-and-sources.txt')])+'</article><article class="pg-card research-entry"><p class="pg-kicker">'+str(source_count)+' reviewed records</p><h2>Evidence appendix</h2><p>Provider and institutional sources, policy scopes, observed dates and uncertainties. Each record keeps its own checked date.</p>'+actions([('Browse the evidence','evidence.html'),('Download evidence JSON','evidence.json')])+'</article></div></section><section id="key-evidence"><h2>The three starting claims</h2>'+actions([('GitHub Classroom shutdown','evidence.html#github'),('Colab education offer','evidence.html#colab'),('AWS Free Tier duration','evidence.html#aws')])+'<p class="pg-small">GitHub repositories and free Colab remain. The six-month AWS boundary is the new general Free Tier, not a blanket reduction to all education or campus accounts.</p></section><section><h2>Focused references</h2><div class="pg-grid">'+''.join('<article class="pg-card"><p class="pg-kicker">'+E(tag)+'</p><h3><a href="'+url+'">'+E(title)+' ↗</a></h3><p>'+E(body)+'</p></article>' for tag,url,title,body in rows)+'</div></section><section><h2>How to read this material</h2><p>Provider checks were collected across October 8–19, 2026. The October 19 overview rechecks selected core sources; it does not reverify every earlier policy. The cumulative report retains earlier dated sections; use the Overview and Staged plan for the current program direction.</p><p>Loss of an education benefit is different from closure of its parent platform. An allocation request is different from an award; local functional tests are different from AWS or CUDA measurements. Neither working storage nor a snapshot proves independent preservation or recovery.</p></section>'

def linked_text(raw):
 result=[];position=0
 for match in re.finditer(r'https?://[^\s<>"\']+',raw):
  result.append(E(raw[position:match.start()]));url=match.group().rstrip('.,;');tail=match.group()[len(url):]
  result.append('<a href="'+E(url,quote=True)+'">'+E(url)+'</a>'+E(tail));position=match.end()
 result.append(E(raw[position:]));return ''.join(result).replace('\n','<br/>')

def full_report_view(text):
 blocks=[];contents=[]
 for i,block in enumerate(text.split('\n\n')):
  if not block.strip():continue
  lines=block.split('\n');first=lines[0]
  heading=first==first.upper() and len(first)<140 and any(c.isalpha() for c in first) and not first.startswith(('http','Source:'))
  if heading:
   anchor='report-section-'+str(i);blocks.append('<h2 id="'+anchor+'">'+E(first)+'</h2>');contents.append((first,'#'+anchor));lines=lines[1:]
  if lines:blocks.append('<p class="report-paragraph">'+linked_text('\n'.join(lines))+'</p>')
 return '<p class="pg-kicker">Complete cumulative research and claim audit</p><h1>Teaching on Borrowed Compute.</h1>'+actions([('Back to report & evidence','report.html'),('Download the full text','research-and-sources.txt'),('Source ledger','evidence.html')])+'<p class="pg-note">This report preserves the dated research and later appendices in full. Some early sections describe earlier stages of the proposal; the current route and zero-cash hours plan are in <a href="program.html">Overview</a> and <a href="timeline.html">Staged plan</a>. Source dates are retained.</p><details class="report-contents"><summary>Jump to a report section</summary><ul>'+''.join('<li><a href="'+url+'">'+E(label)+'</a></li>' for label,url in contents)+'</ul></details><article class="full-report" id="fullReport">'+''.join(blocks)+'</article>'
